export const GLOSSARY: Record<string, readonly [string, string, string, number]> = {
"ability check":["Ability Check","An ability check is a ⟦d20 test|D20 Test⟧ that represents using one of the six abilities—or a specific skill associated with an ability—to overcome a challenge. See also “Playing the Game” (“D20 Tests” and “Proficiency”).","SRD 5.2.1",176],
"action":["Action","On your turn, you can take one action. Choose which action to take from those below or from the special actions provided by your features. See also “Playing the Game” (“Actions”). These actions are defined elsewhere in this glossary:\n• Attack\n• Dash\n• Disengage\n• Dodge\n• Help\n• Hide\n• Influence\n• Magic\n• Ready\n• Search\n• Study\n• Utilize","SRD 5.2.1",176],
"advantage":["Advantage","If you have Advantage on a ⟦d20 test|D20 Test⟧, roll two d20s, and use the higher roll. A roll can’t be affected by more than one Advantage, and Advantage and ⟦disadvantage|Disadvantage⟧ on the same roll cancel each other. See also “Playing the Game” (“D20 Tests”).","SRD 5.2.1",176],
"ammunition":["Ammunition","You can use a weapon that has the Ammunition property to make a ranged attack only if you have ammunition to fire from it. The type of ammunition required is specified with the weapon’s range. Each attack expends one piece of ammunition. Drawing the ammunition is part of the attack (you need a free hand to load a one-handed weapon). After a fight, you can spend 1 minute to recover half the ammunition (round down) you used in the fight; the rest is lost.","SRD 5.2.1",89],
"attack roll":["Attack Roll","An attack roll is a ⟦d20 test|D20 Test⟧ that represents making an attack with a weapon, an ⟦unarmed strike|Unarmed Strike⟧, or a spell. See also “Playing the Game” (“D20 Tests”).","SRD 5.2.1",177],
"blinded":["Blinded","While you have the Blinded condition, you experience the following effects.\nCan’t See. You can’t see and automatically fail any ability check that requires sight.\nAttacks Affected. Attack rolls against you have ⟦advantage|Advantage⟧, and your attack rolls have ⟦disadvantage|Disadvantage⟧.","SRD 5.2.1",177],
"bonus action":["Bonus Action","A Bonus Action is a special action that you can take on the same turn that you take an action. You can’t take more than one Bonus Action on a turn, and you have a Bonus Action to take only if a rule explicitly says so. See also “Playing the Game” (“Actions”).","SRD 5.2.1",177],
"burrow speed":["Burrow Speed","A creature that has a Burrow Speed can use that speed to move through sand, earth, mud, or ice. The creature can’t burrow through solid rock unless the creature has a trait that allows it to do so. See also “Speed.”","SRD 5.2.1",178],
"charmed":["Charmed","While you have the Charmed condition, you experience the following effects.\nCan’t Harm the Charmer. You can’t attack the charmer or target the charmer with damaging abilities or ⟦magical effect|magical effects⟧.\nSocial Advantage. The charmer has ⟦advantage|Advantage⟧ on any ability check to interact with you socially.","SRD 5.2.1",178],
"cleave":["Cleave","If you hit a creature with a melee attack roll using this weapon, you can make a melee attack roll with the weapon against a second creature within 5 feet of the first that is also within your reach. On a hit, the second creature takes the weapon’s damage, but don’t add your ability modifier to that damage unless that modifier is negative. You can make this extra attack only once per turn.","SRD 5.2.1",90],
"climb speed":["Climb Speed","A Climb Speed can be used in place of ⟦speed|Speed⟧ to traverse a vertical surface without expending the extra movement normally associated with climbing. See also “Climbing” and “Speed.”","SRD 5.2.1",179],
"concentration":["Concentration","Some spells and other effects require Concentration to remain active, as specified in their descriptions. If the effect’s creator loses Concentration, the effect ends. If the effect has a maximum duration, the effect’s description specifies how long the creator can concentrate on it: up to 1 minute, 1 hour, or some other duration. The creator can end Concentration at any time (no action required). The following factors break Concentration.\nAnother Concentration Effect. You lose Concentration on an effect the moment you start casting a spell that requires Concentration or activate another effect that requires Concentration.\nDamage. If you take damage, you must succeed on a Constitution ⟦saving throw|saving throw⟧ to maintain Concentration. The DC equals 10 or half the damage taken (round down), whichever number is higher, up to a maximum DC of 30.\nIncapacitated or Dead. Your Concentration ends if you have the ⟦incapacitated|Incapacitated⟧ condition or you die.","SRD 5.2.1",179],
"condition":["Condition","A condition is a temporary game state. The definition of a condition says how it affects its recipient, and various rules define how to end a condition. This glossary defines these conditions:\n• ⟦blinded|Blinded⟧\n• ⟦charmed|Charmed⟧\n• ⟦deafened|Deafened⟧\n• ⟦exhaustion|Exhaustion⟧\n• ⟦frightened|Frightened⟧\n• ⟦grappled|Grappled⟧\n• ⟦incapacitated|Incapacitated⟧\n• ⟦invisible|Invisible⟧\n• ⟦paralyzed|Paralyzed⟧\n• ⟦petrified|Petrified⟧\n• ⟦poisoned|Poisoned⟧\n• ⟦prone|Prone⟧\n• ⟦restrained|Restrained⟧\n• ⟦stunned|Stunned⟧\n• ⟦unconscious|Unconscious⟧\nA condition doesn’t stack with itself; a recipient either has a condition or doesn’t. The ⟦exhaustion|Exhaustion⟧ condition is an exception to that rule.","SRD 5.2.1",179],
"crawling":["Crawling","While you’re crawling, each foot of movement costs 1 extra foot (2 extra feet in ⟦difficult terrain|Difficult Terrain⟧). See also “Speed.”","SRD 5.2.1",179],
"critical hit":["Critical Hit","If you roll a 20 on the d20 for an attack roll, you score a Critical Hit, and the attack hits regardless of any modifiers or the target’s AC. A Critical Hit lets you roll extra dice for the attack’s damage against the target. Roll all of the attack’s damage dice twice and add them together. Then add any relevant modifiers. See also “Playing the Game” (“Damage and Healing”).","SRD 5.2.1",179],
"d20 test":["D20 Test","D20 Tests encompass the three main d20 rolls of the game: ⟦ability check|ability checks⟧, ⟦attack roll|attack rolls⟧, and ⟦saving throw|saving throws⟧. If something in the game affects D20 Tests, it affects all three of these rolls. The GM determines whether a D20 Test is warranted in a given circumstance. See also “Playing the Game” (“D20 Tests”).","SRD 5.2.1",180],
"damage types":["Damage Types","Attacks and other harmful effects deal different types of damage. Damage types have no rules of their own, but other rules, such as Resistance, rely on the types. The Damage Types table offers examples to help a GM assign a type to a new effect.\nAcid | Corrosive liquids, digestive enzymes\nBludgeoning | Blunt objects, constriction, falling\nCold | Freezing water, icy blasts\nFire | Flames, unbearable heat\nForce | Pure magical energy\nLightning | Electricity\nNecrotic | Life-draining energy\nPiercing | Fangs, puncturing objects\nPoison | Toxic gas, venom\nPsychic | Mind-rending energy\nRadiant | Holy energy, searing radiation\nSlashing | Claws, cutting objects\nThunder | Concussive sound","SRD 5.2.1",180],
"deafened":["Deafened","While you have the Deafened condition, you experience the following effect.\nCan’t Hear. You can’t hear and automatically fail any ability check that requires hearing.","SRD 5.2.1",181],
"difficult terrain":["Difficult Terrain","If a space is Difficult Terrain, every foot of movement in that space costs 1 extra foot. For example, moving 5 feet through Difficult Terrain costs 10 feet of movement. Difficult Terrain isn’t cumulative; either a space is Difficult Terrain or it isn’t.\nA space is Difficult Terrain if the space contains any of the following or something similar:\n• A creature that isn’t Tiny or your ally\n• Furniture that is sized for creatures of your size or larger\n• Heavy snow, ice, rubble, or undergrowth\n• Liquid that’s between shin- and waist-deep\n• A narrow opening sized for a creature one size smaller than you\n• A slope of 20 degrees or more","SRD 5.2.1",181],
"disadvantage":["Disadvantage","If you have Disadvantage on a ⟦d20 test|D20 Test⟧, roll two d20s and use the lower roll. A roll can’t be affected by more than one Disadvantage, and ⟦advantage|Advantage⟧ and Disadvantage on the same roll cancel each other. See also “Playing the Game” (“D20 Tests”).","SRD 5.2.1",181],
"exhaustion":["Exhaustion","While you have the Exhaustion condition, you experience the following effects.\nExhaustion Levels. This condition is cumulative. Each time you receive it, you gain 1 Exhaustion level. You die if your Exhaustion level is 6.\nD20 Tests Affected. When you make a D20 Test, the roll is reduced by 2 times your Exhaustion level.\nSpeed Reduced. Your ⟦speed|Speed⟧ is reduced by a number of feet equal to 5 times your Exhaustion level.\nRemoving Exhaustion Levels. Finishing a ⟦long rest|Long Rest⟧ removes 1 of your Exhaustion levels. When your Exhaustion level reaches 0, the condition ends.","SRD 5.2.1",181],
"finesse":["Finesse","When making an attack with a Finesse weapon, use your choice of your Strength or Dexterity modifier for the attack and damage rolls. You must use the same modifier for both rolls.","SRD 5.2.1",89],
"fly speed":["Fly Speed","A Fly Speed can be used to travel through the air. While you have a Fly Speed, you can stay aloft until you land, fall, or die. See also “Flying” and “Speed.”","SRD 5.2.1",182],
"frightened":["Frightened","While you have the Frightened condition, you experience the following effects.\nAbility Checks and Attacks Affected. You have ⟦disadvantage|Disadvantage⟧ on ability checks and attack rolls while the source of fear is within line of sight.\nCan’t Approach. You can’t willingly move closer to the source of fear.","SRD 5.2.1",182],
"grappled":["Grappled","While you have the Grappled condition, you experience the following effects.\nSpeed 0. Your ⟦speed|Speed⟧ is 0 and can’t increase.\nAttacks Affected. You have ⟦disadvantage|Disadvantage⟧ on attack rolls against any target other than the grappler.\nMovable. The grappler can drag or carry you when it moves, but every foot of movement costs it 1 extra foot unless you are Tiny or two or more sizes smaller than it.","SRD 5.2.1",182],
"graze":["Graze","If your attack roll with this weapon misses a creature, you can deal damage to that creature equal to the ability modifier you used to make the attack roll. This damage is the same type dealt by the weapon, and the damage can be increased only by increasing the ability modifier.","SRD 5.2.1",90],
"heavy":["Heavy","You have ⟦disadvantage|Disadvantage⟧ on attack rolls with a Heavy weapon if it’s a Melee weapon and your Strength score isn’t at least 13 or if it’s a Ranged weapon and your Dexterity score isn’t at least 13.","SRD 5.2.1",89],
"hit point dice":["Hit Point Dice","Hit Point Dice, or Hit Dice for short, help determine a ⟦player character|player character’s⟧ Hit Point maximum, as explained in “Character Creation.” Most ⟦monster|monsters⟧ also have Hit Dice. A creature can spend Hit Dice during a ⟦short rest|Short Rest⟧ to regain ⟦hit points|Hit Points⟧. See also “Short Rest.”","SRD 5.2.1",183],
"hit points":["Hit Points","Hit Points (HP) are a measure of how difficult it is to kill or destroy a creature or an object. Damage reduces Hit Points, and healing restores them. You can’t have more Hit Points than your Hit Point maximum, and you can’t have less than 0. See also “Breaking Objects” and “Playing the Game” (“Damage and Healing”).","SRD 5.2.1",183],
"immunity":["Immunity","If you have Immunity to a ⟦damage types|damage type⟧ or a ⟦condition|condition⟧, it doesn’t affect you in any way.","SRD 5.2.1",183],
"incapacitated":["Incapacitated","While you have the Incapacitated condition, you experience the following effects.\nInactive. You can’t take any ⟦action|action⟧, ⟦bonus action|Bonus Action⟧, or ⟦reaction|Reaction⟧.\nNo Concentration. Your ⟦concentration|Concentration⟧ is broken.\nSpeechless. You can’t speak.\nSurprised. If you’re Incapacitated when you roll ⟦initiative|Initiative⟧, you have ⟦disadvantage|Disadvantage⟧ on the roll.","SRD 5.2.1",184],
"initiative":["Initiative","Initiative determines the order of turns during combat. The combat rules in “Playing the Game” explain how to roll Initiative.\nSometimes a GM might have combatants use their Initiative scores instead of rolling Initiative. Your Initiative score equals 10 plus your Dexterity modifier. If you have ⟦advantage|Advantage⟧ on Initiative rolls, increase your Initiative score by 5. If you have ⟦disadvantage|Disadvantage⟧ on those rolls, decrease that score by 5. See also “Playing the Game” (“Combat”).","SRD 5.2.1",184],
"invisible":["Invisible","While you have the Invisible condition, you experience the following effects.\nSurprise. If you’re Invisible when you roll ⟦initiative|Initiative⟧, you have ⟦advantage|Advantage⟧ on the roll.\nConcealed. You aren’t affected by any effect that requires its target to be seen unless the effect’s creator can somehow see you. Any equipment you are wearing or carrying is also concealed.\nAttacks Affected. Attack rolls against you have ⟦disadvantage|Disadvantage⟧, and your attack rolls have ⟦advantage|Advantage⟧. If a creature can somehow see you, you don’t gain this benefit against that creature.","SRD 5.2.1",184],
"light":["Light","When you take the Attack action on your turn and attack with a Light weapon, you can make one extra attack as a ⟦bonus action|Bonus Action⟧ later on the same turn. That extra attack must be made with a different Light weapon, and you don’t add your ability modifier to the extra attack’s damage unless that modifier is negative. For example, you can attack with a ⟦item:Shortsword|Shortsword⟧ in one hand and a ⟦item:Dagger|Dagger⟧ in the other using the Attack action and a ⟦bonus action|Bonus Action⟧, but you don’t add your Strength or Dexterity modifier to the damage roll of the ⟦bonus action|Bonus Action⟧ unless that modifier is negative.","SRD 5.2.1",89],
"loading":["Loading","You can fire only one piece of ammunition from a Loading weapon when you use an action, a ⟦bonus action|Bonus Action⟧, or a ⟦reaction|Reaction⟧ to fire it, regardless of the number of attacks you can normally make.","SRD 5.2.1",90],
"long rest":["Long Rest","A Long Rest is a period of extended downtime—at least 8 hours—available to any creature. During a Long Rest, you sleep for at least 6 hours and perform no more than 2 hours of light activity, such as reading, talking, eating, or standing watch.\nDuring sleep, you have the ⟦unconscious|Unconscious⟧ condition. After you finish a Long Rest, you must wait at least 16 hours before starting another one.\nBenefits of the Rest. To start a Long Rest, you must have at least 1 ⟦hit points|Hit Point⟧. When you finish the rest, you gain the following benefits:\n• Regain All HP. You regain all lost ⟦hit points|Hit Points⟧ and all spent ⟦hit point dice|Hit Point Dice⟧. If your Hit Point maximum was reduced, it returns to normal.\n• Ability Scores Restored. If any of your ability scores were reduced, they return to normal.\n• Exhaustion Reduced. If you have the ⟦exhaustion|Exhaustion⟧ condition, its level decreases by 1.\n• Special Feature. Some features are recharged by a Long Rest. If you have such a feature, it recharges in the way specified in its description.\nInterrupting the Rest. A Long Rest is stopped by the following interruptions:\n• Rolling ⟦initiative|Initiative⟧\n• Casting a spell other than a cantrip\n• Taking any damage\n• 1 hour of walking or other physical exertion\nIf you rested at least 1 hour before the interruption, you gain the benefits of a ⟦short rest|Short Rest⟧. See also “Short Rest.”\nYou can resume a Long Rest immediately after an interruption. If you do so, the rest requires 1 additional hour per interruption to finish.","SRD 5.2.1",185],
"magical effect":["Magical Effect","An effect is magical if it is created by a spell, a magic item, or a phenomenon that a rule labels as magical.","SRD 5.2.1",185],
"monster":["Monster","A monster is a creature controlled by the GM, even if the creature is benevolent. See also “Creature” and “NPC.”","SRD 5.2.1",185],
"nick":["Nick","When you make the extra attack of the Light property, you can make it as part of the Attack action instead of as a ⟦bonus action|Bonus Action⟧. You can make this extra attack only once per turn.","SRD 5.2.1",90],
"paralyzed":["Paralyzed","While you have the Paralyzed condition, you experience the following effects.\nIncapacitated. You have the ⟦incapacitated|Incapacitated⟧ condition.\nSpeed 0. Your ⟦speed|Speed⟧ is 0 and can’t increase.\nSaving Throws Affected. You automatically fail Strength and Dexterity ⟦saving throw|saving throws⟧.\nAttacks Affected. Attack rolls against you have ⟦advantage|Advantage⟧.\nAutomatic Critical Hits. Any attack roll that hits you is a ⟦critical hit|Critical Hit⟧ if the attacker is within 5 feet of you.","SRD 5.2.1",186],
"petrified":["Petrified","While you have the Petrified condition, you experience the following effects.\nTurned to Inanimate Substance. You are transformed, along with any nonmagical objects you are wearing and carrying, into a solid inanimate substance (usually stone). Your weight increases by a factor of ten, and you cease aging.\nIncapacitated. You have the ⟦incapacitated|Incapacitated⟧ condition.\nSpeed 0. Your ⟦speed|Speed⟧ is 0 and can’t increase.\nAttacks Affected. Attack rolls against you have ⟦advantage|Advantage⟧.\nSaving Throws Affected. You automatically fail Strength and Dexterity ⟦saving throw|saving throws⟧.\nResist Damage. You have ⟦resistance|Resistance⟧ to all damage.\nPoison Immunity. You have ⟦immunity|Immunity⟧ to the ⟦poisoned|Poisoned⟧ condition.","SRD 5.2.1",186],
"player character":["Player Character","A player character is a character controlled by a player. See also “Character Creation.”","SRD 5.2.1",186],
"poisoned":["Poisoned","While you have the Poisoned condition, you experience the following effect.\nAbility Checks and Attacks Affected. You have ⟦disadvantage|Disadvantage⟧ on attack rolls and ability checks.","SRD 5.2.1",186],
"proficiency":["Proficiency","If you have proficiency with something, you can add your Proficiency Bonus to any ⟦d20 test|D20 Test⟧ you make using that thing. A creature might have proficiency in a skill or ⟦saving throw|saving throw⟧ or with a weapon or tool. See also “Playing the Game” (“Proficiency”).","SRD 5.2.1",186],
"prone":["Prone","While you have the Prone condition, you experience the following effects.\nRestricted Movement. Your only movement options are to ⟦crawling|crawl⟧ or to spend an amount of movement equal to half your ⟦speed|Speed⟧ (round down) to right yourself and thereby end the condition. If your ⟦speed|Speed⟧ is 0, you can’t right yourself.\nAttacks Affected. You have ⟦disadvantage|Disadvantage⟧ on attack rolls. An attack roll against you has ⟦advantage|Advantage⟧ if the attacker is within 5 feet of you. Otherwise, that attack roll has ⟦disadvantage|Disadvantage⟧.","SRD 5.2.1",186],
"push":["Push","If you hit a creature with this weapon, you can push the creature up to 10 feet straight away from yourself if it is Large or smaller.","SRD 5.2.1",90],
"reach":["Reach","A Reach weapon adds 5 feet to your reach when you attack with it, as well as when determining your reach for Opportunity Attacks with it.","SRD 5.2.1",90],
"reaction":["Reaction","A Reaction is a special action taken in response to a trigger defined in the Reaction’s description. You can take a Reaction on another creature’s turn, and if you take it on your turn, you can do so even if you also take an action, a ⟦bonus action|Bonus Action⟧, or both. Once you take a Reaction, you can’t take another one until the start of your next turn. The Opportunity Attack is a Reaction available to all creatures. See also “Opportunity Attacks” and “Playing the Game” (“Actions”).","SRD 5.2.1",186],
"resistance":["Resistance","If you have Resistance to a ⟦damage types|damage type⟧, damage of that type is halved against you (round down). Resistance is applied only once to an instance of damage. See also “Playing the Game” (“Damage and Healing”).","SRD 5.2.1",187],
"restrained":["Restrained","While you have the Restrained condition, you experience the following effects.\nSpeed 0. Your ⟦speed|Speed⟧ is 0 and can’t increase.\nAttacks Affected. Attack rolls against you have ⟦advantage|Advantage⟧, and your attack rolls have ⟦disadvantage|Disadvantage⟧.\nSaving Throws Affected. You have ⟦disadvantage|Disadvantage⟧ on Dexterity ⟦saving throw|saving throws⟧.","SRD 5.2.1",187],
"sap":["Sap","If you hit a creature with this weapon, that creature has ⟦disadvantage|Disadvantage⟧ on its next attack roll before the start of your next turn.","SRD 5.2.1",90],
"saving throw":["Saving Throw","A saving throw—also called a save—represents an attempt to avoid or resist a threat. You normally make a saving throw only when a rule requires you to do so, but you can decide to fail the save without rolling. The result of a save is detailed in the effect that allowed it. If a target is forced to make a save and lacks the ability score used by it, the target automatically fails. See also “Playing the Game” (“D20 Tests”).","SRD 5.2.1",187],
"short rest":["Short Rest","A Short Rest is a 1-hour period of downtime, during which a creature does nothing more strenuous than reading, talking, eating, or standing watch. To start a Short Rest, you must have at least 1 ⟦hit points|Hit Point⟧.\nBenefits of the Rest. When you finish the rest, you gain the following benefits:\n• Spend Hit Point Dice. You can spend one or more of your ⟦hit point dice|Hit Point Dice⟧ to regain ⟦hit points|Hit Points⟧. For each ⟦hit point dice|Hit Point Die⟧ you spend in this way, roll the die and add your Constitution modifier to it. You regain ⟦hit points|Hit Points⟧ equal to the total (minimum of 1 Hit Point). You can decide to spend an additional ⟦hit point dice|Hit Point Die⟧ after each roll.\n• Special Feature. Some features are recharged by a Short Rest. If you have such a feature, it recharges in the way specified in its description.\nInterrupting the Rest. A Short Rest is stopped by the following interruptions:\n• Rolling ⟦initiative|Initiative⟧\n• Casting a spell other than a cantrip\n• Taking any damage\nAn interrupted Short Rest confers no benefits.","SRD 5.2.1",187],
"slow":["Slow","If you hit a creature with this weapon and deal damage to it, you can reduce its ⟦speed|Speed⟧ by 10 feet until the start of your next turn. If the creature is hit more than once by weapons that have this property, the ⟦speed|Speed⟧ reduction doesn’t exceed 10 feet.","SRD 5.2.1",90],
"speed":["Speed","A creature has a Speed, which is the distance in feet the creature can cover when it moves on its turn. See also “Climbing,” “Crawling,” “Flying,” “Jumping,” “Swimming” and “Playing the Game” (“Combat”).\nSpecial Speeds. Some creatures have special speeds, such as a ⟦burrow speed|Burrow Speed⟧, ⟦climb speed|Climb Speed⟧, ⟦fly speed|Fly Speed⟧, or ⟦swim speed|Swim Speed⟧, each of which is defined in this glossary. If you have more than one speed, choose which one to use when you move; you can switch between the speeds during your move. Whenever you switch, subtract the distance already moved from the new speed. The result determines how much farther you can move. If the result is 0 or less, you can’t use the new speed during the current move. For example, if you have a Speed of 30 and a ⟦fly speed|Fly Speed⟧ of 40, you could fly 10 feet, walk 10 feet, and leap into the air to fly 20 feet more.\nChanges to Your Speeds. If an effect increases or decreases your Speed for a time, any special speed you have increases or decreases by an equal amount for the same duration. For example, if your Speed is reduced to 0 and you have a ⟦climb speed|Climb Speed⟧, your ⟦climb speed|Climb Speed⟧ is also reduced to 0. Similarly, if your Speed is halved and you have a ⟦fly speed|Fly Speed⟧, your ⟦fly speed|Fly Speed⟧ is also halved.","SRD 5.2.1",188],
"stunned":["Stunned","While you have the Stunned condition, you experience the following effects.\nIncapacitated. You have the ⟦incapacitated|Incapacitated⟧ condition.\nSaving Throws Affected. You automatically fail Strength and Dexterity ⟦saving throw|saving throws⟧.\nAttacks Affected. Attack rolls against you have ⟦advantage|Advantage⟧.","SRD 5.2.1",189],
"swim speed":["Swim Speed","A Swim Speed can be used to swim without expending the extra movement normally associated with swimming. See also “Swimming” and “Speed.”","SRD 5.2.1",189],
"thrown":["Thrown","If a weapon has the Thrown property, you can throw the weapon to make a ranged attack, and you can draw that weapon as part of the attack. If the weapon is a Melee weapon, use the same ability modifier for the attack and damage rolls that you use for a melee attack with that weapon.","SRD 5.2.1",90],
"topple":["Topple","If you hit a creature with this weapon, you can force the creature to make a Constitution saving throw (DC 8 plus the ability modifier used to make the attack roll and your ⟦proficiency|Proficiency Bonus⟧). On a failed save, the creature has the ⟦prone|Prone⟧ condition.","SRD 5.2.1",90],
"two-handed":["Two-Handed","A Two-Handed weapon requires two hands when you attack with it.","SRD 5.2.1",90],
"unarmed strike":["Unarmed Strike","Instead of using a weapon to make a melee attack, you can use a punch, kick, headbutt, or similar forceful blow. In game terms, this is an Unarmed Strike—a melee attack that involves you using your body to damage, grapple, or shove a target within 5 feet of you.\nWhenever you use your Unarmed Strike, choose one of the following options for its effect.\nDamage. You make an attack roll against the target. Your bonus to the roll equals your Strength modifier plus your ⟦proficiency|Proficiency Bonus⟧. On a hit, the target takes Bludgeoning damage equal to 1 plus your Strength modifier.\nGrapple. The target must succeed on a Strength or Dexterity ⟦saving throw|saving throw⟧ (it chooses which), or it has the ⟦grappled|Grappled⟧ condition. The DC for the ⟦saving throw|saving throw⟧ and any escape attempts equals 8 plus your Strength modifier and ⟦proficiency|Proficiency Bonus⟧. This grapple is possible only if the target is no more than one size larger than you and if you have a hand free to grab it. See also “Grappling.”\nShove. The target must succeed on a Strength or Dexterity ⟦saving throw|saving throw⟧ (it chooses which), or you either push it 5 feet away or cause it to have the ⟦prone|Prone⟧ condition. The DC for the ⟦saving throw|saving throw⟧ equals 8 plus your Strength modifier and ⟦proficiency|Proficiency Bonus⟧. This shove is possible only if the target is no more than one size larger than you.","SRD 5.2.1",190],
"unconscious":["Unconscious","While you have the Unconscious condition, you experience the following effects.\nInert. You have the ⟦incapacitated|Incapacitated⟧ and ⟦prone|Prone⟧ conditions, and you drop whatever you’re holding. When this condition ends, you remain ⟦prone|Prone⟧.\nSpeed 0. Your ⟦speed|Speed⟧ is 0 and can’t increase.\nAttacks Affected. Attack rolls against you have ⟦advantage|Advantage⟧.\nSaving Throws Affected. You automatically fail Strength and Dexterity ⟦saving throw|saving throws⟧.\nAutomatic Critical Hits. Any attack roll that hits you is a ⟦critical hit|Critical Hit⟧ if the attacker is within 5 feet of you.\nUnaware. You’re unaware of your surroundings.","SRD 5.2.1",191],
"versatile":["Versatile","A Versatile weapon can be used with one or two hands. A damage value in parentheses appears with the property. The weapon deals that damage when used with two hands to make a melee attack.","SRD 5.2.1",90],
"vex":["Vex","If you hit a creature with this weapon and deal damage to the creature, you have ⟦advantage|Advantage⟧ on your next attack roll against that creature before the end of your next turn.","SRD 5.2.1",90],
}
